int a = 5, b = 3, c = 2;

// Default Precedence: Multiplication before Addition
int result_default = a + b * c;    // 5 + (3 * 2) = 11

// Override: Parentheses force Addition first
int result_forced = (a + b) * c;   // (5 + 3) * 2 = 16

// Associativity/Precedence Control in Declarations

// Default: Array of 5 pointers to int ( [] binds tighter than * )
int* default_ptr_array[5];

// Override: Pointer to an array of 5 ints
int (*forced_array_ptr)[5];

// Override: Function pointer declaration
int (*func_ptr)(int, int);
